import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mk2 import *

page(dict(
 slug='pollock',
 title=T('물감을 마구 뿌리면 폴록이 될까?', 'If You Fling Paint at Random, Do You Get a Pollock?'),
 title_tag=T('물감을 마구 뿌리면 폴록이 될까? · 시뮬라티오 랩', 'Fling Paint at Random, Get a Pollock? · Simulatio Lab'),
 desc=T('붓이 무작위로 걸으며 물감을 뿌리고, 그림의 복잡도를 칸 세기로 잽니다. 구불구불한 붓질, 자로 그은 직선, 무작위 점을 같은 물감 양으로 비교해 보세요.',
        'A brush wanders at random flinging paint, and the picture\'s complexity is measured by counting boxes. Compare wandering brushwork, ruled straight lines and random dots with the same amount of paint.'),
 lead=T('잭슨 폴록의 그림은 물감을 아무렇게나 흩뿌린 것처럼 보입니다. 그런데 그 얽힌 선 속에 큰 칸으로 보나 작은 칸으로 보나 비슷하게 복잡한 &#39;프랙탈&#39; 성격이 있다는 연구가 있고, 그 분석에 대한 반론도 있습니다. 그렇다면 컴퓨터 붓이 무작위로 걸으며 뿌린 그림은 몇 점짜리 복잡도가 나올까요? 그리고 자로 반듯하게 그은 직선 다발은 그보다 훨씬 낮게 나올까요? 직접 뿌리고 재 보세요.',
        'Jackson Pollock\'s paintings look as if paint was flung about any old way. Yet one study reported a fractal character in those tangled lines, similarly complex whether you look with big boxes or small ones, and that analysis has also been disputed. So what complexity score does a picture get when a computer brush wanders at random? And would a bundle of straight lines drawn with a ruler score far lower? Fling the paint and measure it yourself.'),
 model=[T('붓 끝이 캔버스 위를 한 걸음씩 나아갑니다. 걸음마다 방향을 조금씩 무작위로 틀고(<b>방향을 트는 정도</b>), 벽에 닿으면 튕겨 나옵니다. <b>한 획의 길이</b>만큼 그으면 붓을 들어 아무 곳에서 새 획을 시작하고, 색과 굵기도 새로 고릅니다.',
          'The brush tip moves across the canvas one step at a time. At each step it turns a little at random (<b>how much it turns</b>), and it bounces off the edges. After one <b>stroke length</b> it lifts and starts a new stroke somewhere else, with a new color and thickness.'),
        T('<b>뿌리는 물감 양</b>은 모든 획의 길이를 더한 값입니다(캔버스 너비의 몇 배인지). 같은 물감 양으로 <b>자로 그은 직선</b>(무작위 위치·방향의 곧은 선)과 <b>무작위 점</b>(캔버스 전체에 고르게 찍은 점)도 함께 그려 비교합니다.',
          'The <b>amount of paint</b> is the total length of all strokes (as a multiple of the canvas width). With the same amount, the page also draws <b>ruled straight lines</b> (straight lines at random places and angles) and <b>random dots</b> (spread evenly over the canvas) for comparison.'),
        T('복잡도는 <b>칸 세기</b>로 잽니다. 캔버스를 큰 칸, 중간 칸, 작은 칸으로 나눠 물감이 묻은 칸을 셉니다. 칸 한 변을 4분의 1로 줄이면(칸 수 16배) 묻은 칸이 4배로 늘 때는 선 같은 그림, 16배로 늘 때는 면 같은 그림입니다.',
          'Complexity is measured by <b>counting boxes</b>. The canvas is split into big, medium and small boxes, and the boxes with paint are counted. When the box side shrinks to a quarter (16 times as many boxes), the count rising 4 times means the picture behaves like a line, and 16 times like a filled area.'),
        T('그 늘어나는 정도를 숫자 하나로 만든 것이 <b>복잡도(프랙탈 차원)</b>입니다. 반듯한 선 한 줄이면 1, 빈틈없이 칠한 면이면 2이고, 1과 2 사이면 &#39;선이지만 면을 채워 가는&#39; 그림입니다. 이 숫자는 그림이 좋은지 나쁜지를 재지 않습니다.',
          'Turning that rate of growth into a single number gives the <b>complexity (fractal dimension)</b>. One straight line gives 1 and a solidly painted area gives 2; between 1 and 2 is a picture made of lines that are filling in the area. This number does not measure whether a picture is good or bad.')],
 sliders=[('turn', T('방향을 트는 정도', 'How much the brush turns'), 0, 120, 2, 10, T('올리면 붓이 자주 꺾여 한곳에 뭉치고, 0이면 곧게 뻗어요', 'Higher makes the brush bend often and bunch up in one spot; 0 runs straight')),
          ('stroke', T('한 획의 길이', 'Length of one stroke'), 0.2, 4, 0.2, 1.2, T('올리면 붓을 덜 떼고 길게 이어 그어요', 'Higher means the brush lifts less often and draws longer lines')),
          ('amount', T('뿌리는 물감 양', 'Amount of paint'), 10, 200, 10, 60, T('올리면 캔버스가 더 빽빽하게 덮여요 (선 길이 합)', 'Higher covers the canvas more densely (total line length)'))],
 selects=[('mode', T('그리는 방식', 'How to paint'), [('brush', T('구불구불한 붓질', 'Wandering brushwork')), ('ruler', T('비교: 자로 그은 직선', 'Comparison: ruled straight lines')), ('dots', T('비교: 무작위 점', 'Comparison: random dots'))], 'brush',
           T('비교 방식으로 바꾸면 같은 물감 양에서 숫자가 어떻게 되는지 볼 수 있어요', 'Switch to a comparison to see what number the same amount of paint gives'))],
 reroll=T('같은 설정, 다른 붓질', 'Same settings, new brushwork'),
 sections=[
  dict(title=T('① 붓이 걸으며 뿌리는 그림', '① A Picture Flung by a Wandering Brush'),
       p=T('흰 동그라미가 지금 붓 끝입니다. 오른쪽(휴대폰은 아래) 숫자가 지금까지 그린 그림의 복잡도이고, 눈금자 위의 다른 색 표시는 같은 물감 양을 다른 방식으로 뿌렸을 때의 값입니다(지금까지 쓴 양까지만).',
           'The white circle is the brush tip right now. The number on the right (below on phones) is the complexity of the picture so far, and the other colored marks on the scale are what the same amount of paint scores when flung another way (only up to the amount used so far).'),
       id='c-paint', rounded=True, anim=True, thumb=True,
       speeds=[('10', T('느리게', 'Slow')), ('30', T('보통', 'Normal')), ('80', T('빠르게', 'Fast'))], speed_default='30'),
  dict(title=T('② 칸을 줄여 가며 물감 묻은 칸 세기', '② Counting Painted Boxes as the Boxes Shrink'),
       p=T('지금 그림을 큰 칸(8×8), 중간 칸(32×32), 작은 칸(128×128)으로 나눠 물감이 묻은 칸을 파랗게 칠했습니다. 칸이 작아질수록 묻은 칸이 얼마나 빨리 늘어나는지가 복잡도입니다.',
           'The current picture split into big (8×8), medium (32×32) and small (128×128) boxes, with painted boxes shown in blue. How fast the painted count grows as the boxes shrink is the complexity.'),
       id='c-box'),
  dict(title=T('③ 칸 크기와 묻은 칸 수 (로그 눈금)', '③ Box Size and Painted Boxes (Log Scales)'),
       p=T('가로는 칸 한 변(오른쪽일수록 작은 칸), 세로는 물감 묻은 칸 수이고 둘 다 로그 눈금입니다. 파란 바탕 범위의 점들에 맞춘 빨간 선의 기울기가 복잡도입니다. 회색 점선은 기울기 1(선)과 2(면)입니다.',
           'Across is the box side (smaller boxes to the right) and up is the number of painted boxes, both on log scales. The slope of the red line fitted to the dots in the blue band is the complexity. The gray dashed lines are slope 1 (a line) and 2 (an area).'),
       id='c-loglog'),
  dict(title=T('④ 물감이 늘수록 복잡도는 (지금까지)', '④ Complexity as the Paint Builds Up (So Far)'),
       p=T('지금 그림의 복잡도가 물감을 뿌리는 동안 어떻게 바뀌었는지입니다. 점선은 같은 양까지 다른 방식으로 뿌렸을 때입니다. 재생이 도달한 곳까지만 그립니다.',
           'How the complexity of the current picture changed while the paint was flung. The dashed lines are the other ways of flinging the same amount. Only drawn up to where playback has reached.'),
       id='c-grow'),
  dict(title=T('⑤ 방향을 트는 정도별 복잡도 (세 번씩 끝까지 그린 집계)', '⑤ Complexity by How Much the Brush Turns (Totals of Three Full Pictures Each)'),
       p=T('지금의 한 획 길이와 물감 양으로 방향을 트는 정도만 바꿔 그림을 세 장씩 끝까지 그린 뒤 잰 값입니다(점 하나가 그림 한 장). 점선은 같은 물감 양의 자로 그은 직선과 무작위 점입니다.',
           'With the current stroke length and amount of paint, only the turning is changed, and three full pictures are drawn for each value (one dot per picture). The dashed lines are ruled straight lines and random dots with the same amount of paint.'),
       id='c-sweep'),
 ],
 says=T('기본값(방향을 트는 정도 10°, 한 획 캔버스 너비 1.2배, 물감 캔버스 너비 60배)으로 그림 8장을 그리면 복잡도는 평균 1.74(범위 1.72~1.75), 캔버스의 19%를 덮었습니다. 같은 물감 양의 자로 그은 직선은 1.75로 거의 같았고, 무작위 점은 1.93이었습니다. 숫자를 가장 크게 움직인 것은 물감 양이었습니다. 물감이 캔버스 너비 10배일 때 붓질은 1.24, 30배 1.54, 60배 1.74, 120배 1.90, 200배 1.96이었고, 자로 그은 직선도 1.23, 1.54, 1.75, 1.90, 1.96으로 거의 같은 길을 따랐습니다. 같은 물감 양에서 방향을 자주 틀수록 붓이 한곳에 뭉쳐 숫자가 내려갔습니다. 세 장씩 그린 평균은 0°와 15°에서 1.74, 45°에서 1.64, 90°에서 1.49, 120°에서 1.41이었고, 덮은 넓이도 19%에서 10%로 줄었습니다.',
       'With the defaults (turning 10°, stroke 1.2 canvas widths, paint 60 canvas widths), eight pictures averaged a complexity of 1.74 (range 1.72 to 1.75) and covered 19% of the canvas. Ruled straight lines with the same amount of paint scored 1.75, almost the same, and random dots 1.93. What moved the number most was the amount of paint. At 10 canvas widths of paint the brushwork scored 1.24, at 30 1.54, at 60 1.74, at 120 1.90 and at 200 1.96, while ruled lines followed almost the same path: 1.23, 1.54, 1.75, 1.90, 1.96. With the same amount of paint, turning more often bunched the brush up in places and lowered the number. Averages of three pictures were 1.74 at 0° and 15°, 1.64 at 45°, 1.49 at 90° and 1.41 at 120°, and the covered area shrank from 19% to 10%.'),
 **{'not': T('이 그림들은 폴록의 그림을 재현한 것이 아니고, 폴록이 어떻게 그렸는지도 보여 주지 않습니다. 폴록의 그림에서 프랙탈 성격을 보고한 연구가 있고 그 분석에 대한 반론도 있는데, 이 페이지는 그 논쟁의 어느 쪽이 맞는지 가리지 않으며 그 연구들의 수치를 쓰지 않았습니다. 이 페이지가 보여 주는 것은 이 프로젝트가 정한 단순한 붓 걷기와 칸 세기에서, 복잡도 숫자가 물감 양(덮은 넓이)에 크게 좌우되고 자로 그은 직선도 같은 양이면 비슷한 숫자를 낸다는 것뿐입니다. 숫자는 캔버스 크기, 붓 굵기, 기울기를 잰 칸 크기 범위에 따라서도 달라집니다. 그리고 이 숫자는 인기나 아름다움, 작품의 좋고 나쁨을 재지 않습니다. 같은 숫자라도 그림이 주는 느낌이나 예술적 가치는 전혀 다를 수 있고, 이 모델은 그것을 판단하지 않습니다.',
      'These pictures do not reproduce Pollock\'s paintings, nor do they show how Pollock painted. One study reported a fractal character in Pollock\'s paintings and that analysis has been disputed; this page does not decide which side of that debate is right and uses none of those studies\' figures. All it shows is that, with this project\'s simple wandering brush and box counting, the complexity number depends heavily on the amount of paint (the area covered), and ruled straight lines give a similar number with the same amount. The number also changes with canvas size, brush thickness and the range of box sizes used for the slope. And the number does not measure popularity, beauty, or whether a work is good or bad. Pictures with the same number can feel completely different and have entirely different artistic value, and this model makes no judgment about that.')},
 theory=[
  ('root', T('복잡도를 재는 칸 세기(box-counting)는 프랙탈 기하학에서 쓰는 차원 측정법입니다(Mandelbrot의 프랙탈 기하학). 그림에 이를 적용한 연구로 Taylor, Micolich, Jonas (1999), "Fractal analysis of Pollock\'s drip paintings", Nature 399: 422가 폴록의 그림에서 프랙탈 성격을 보고했고, 이에 대한 반론도 있습니다(예: Jones-Smith &amp; Mathur (2006), Nature 444: E9–E10). 이 페이지는 그 주장과 반론을 판정하지 않습니다.',
             'Box counting is a way of measuring dimension used in fractal geometry (Mandelbrot\'s fractal geometry). Applying it to paintings, Taylor, Micolich and Jonas (1999), "Fractal analysis of Pollock\'s drip paintings", Nature 399: 422, reported a fractal character in Pollock\'s paintings, and there are rebuttals (for example Jones-Smith &amp; Mathur (2006), Nature 444: E9–E10). This page does not judge between the claim and the rebuttals.')),
  ('model', T('칸 한 변이 <i>s</i>일 때 물감 묻은 칸 수 <i>N(s)</i>가 <i>N(s) ∝ s<sup>−D</sup></i>라면 <i>D</i>가 칸 세기 차원입니다. 반듯한 선은 <i>D</i> = 1, 꽉 찬 면은 <i>D</i> = 2입니다. 붓은 걸음마다 방향을 정규분포(표준편차 = &#39;방향을 트는 정도&#39;)로 틀며, 한 획의 길이와 물감 양(획 길이의 합)은 슬라이더로 정합니다.',
             'If the number of painted boxes <i>N(s)</i> for box side <i>s</i> follows <i>N(s) ∝ s<sup>−D</sup></i>, then <i>D</i> is the box-counting dimension. A straight line has <i>D</i> = 1 and a filled area <i>D</i> = 2. At each step the brush turns by a normal random angle (standard deviation = "how much the brush turns"), and the stroke length and amount of paint (total stroke length) are set by sliders.')),
  ('simplify', T('캔버스는 512×512칸, 한 걸음은 2칸, 붓 굵기는 1·2·3·5칸 중 무작위이고, 기울기는 칸 한 변 4·8·16·32·64칸(캔버스 너비의 1/128~1/8)에서 최소제곱으로 잽니다. 이 값들은 모두 이 프로젝트가 정한 것이며, 실제 그림 분석에서 쓰는 사진 해상도·범위 선택과는 다릅니다. 물감이 흘러내리거나 번지는 물리는 넣지 않았습니다.',
                 'The canvas is 512 × 512 cells, one step is 2 cells, brush thickness is randomly 1, 2, 3 or 5 cells, and the slope is fitted by least squares over box sides of 4, 8, 16, 32 and 64 cells (1/128 to 1/8 of the canvas width). All of these are this project\'s choices and differ from the photo resolution and range choices of real painting analyses. The physics of paint dripping or spreading is left out.')),
  ('check', T('닫힌 이론값과 비교할 대상은 없어, 기준이 되는 두 그림으로 확인했습니다. 같은 물감 양에서 자로 그은 직선은 평균 1.75, 무작위 점은 1.93이었고, 기본 붓질은 1.74였습니다. 물감을 캔버스 너비 200배까지 늘리면 세 방식 모두 2에 가까워졌습니다(붓질·직선 1.96, 점 2.00). 즉 이 범위의 칸 세기 숫자는 선의 모양보다 덮은 넓이를 더 많이 반영합니다.',
             'There is no closed-form value to compare against, so two reference pictures were used. With the same amount of paint, ruled straight lines averaged 1.75 and random dots 1.93, against 1.74 for the default brushwork. Raising the paint to 200 canvas widths brought all three close to 2 (brushwork and lines 1.96, dots 2.00). So within this range of boxes, the box-counting number reflects the covered area more than the shape of the lines.')),
  ('read', T('Taylor, Micolich &amp; Jonas (1999), Nature 399: 422. Jones-Smith &amp; Mathur (2006), Nature 444: E9–E10. Mandelbrot, 『The Fractal Geometry of Nature』(W. H. Freeman, 1982).',
             'Taylor, Micolich &amp; Jonas (1999), Nature 399: 422. Jones-Smith &amp; Mathur (2006), Nature 444: E9–E10. Mandelbrot, <i>The Fractal Geometry of Nature</i> (W. H. Freeman, 1982).')),
 ],
 memo=[T('시뮬레이션은 시드 난수(mulberry32)를 쓰고 같은 시드면 같은 그림이 나옵니다. 칸 수는 새 칸에 물감이 처음 묻을 때마다 모든 칸 크기에서 바로 더해 세므로, 재생 중의 숫자가 언제나 지금 그림의 값입니다.',
         'The simulation uses a seeded random generator (mulberry32), so the same seed gives the same picture. Box counts are updated at every box size whenever a cell first gets paint, so the number during playback is always that of the current picture.'),
       T('비교용 그림(자로 그은 직선·무작위 점)은 같은 설정과 그림 번호로 따로 그려 두고, 화면에는 지금 쓴 물감 양까지의 값만 보여 줍니다. ⑤는 그림 101~103번으로 끝까지 그린 집계입니다. 검증은 <code>node tools/validate-pollock.js</code>로 할 수 있습니다.',
         'The comparison pictures (ruled lines and random dots) are drawn separately with the same settings and picture number, and only their values up to the amount of paint used so far are shown. Chart ⑤ is a total of full pictures numbered 101 to 103. You can verify with <code>node tools/validate-pollock.js</code>.')],
))
